--
-- TOC entry 520 (class 1255 OID 97109)
-- Name: fn_validar_reserva_antes_save(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_reserva_antes_save() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  conflito_aula BOOLEAN;
  conflito_reserva BOOLEAN;
  versao_ativa_id UUID;
BEGIN
  -- 1. Descobre a versão publicada mais recente que já está em vigor
  SELECT id INTO versao_ativa_id
  FROM versoes_grade
  WHERE status = 'PUBLICADA' AND data_inicio_vigencia <= CURRENT_DATE
  ORDER BY data_inicio_vigencia DESC
  LIMIT 1;

  -- Se não houver, pega a última publicada (mesmo no futuro ou sem data)
  IF versao_ativa_id IS NULL THEN
    SELECT id INTO versao_ativa_id
    FROM versoes_grade
    WHERE status = 'PUBLICADA'
    ORDER BY data_inicio_vigencia DESC, criado_em DESC
    LIMIT 1;
  END IF;

  -- 2. Verifica choque com a grade de aulas fixa APENAS da versão ativa encontrada
  IF versao_ativa_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM aulas a
      WHERE a.espaco_id = NEW.espaco_id
        AND a.dia_semana = NEW.dia_semana
        AND a.slot_horario_id = NEW.slot_horario_id
        AND a.versao_id = versao_ativa_id
    ) INTO conflito_aula;

    IF conflito_aula THEN
      RAISE EXCEPTION 'Conflito detectado: Este espaço possui uma aula fixa na grade oficial atual.';
    END IF;
  END IF;

  -- 3. Verifica choque com outra reserva manual na MESMA DATA específica
  SELECT EXISTS (
    SELECT 1 FROM reservas_espacos r
    WHERE r.espaco_id = NEW.espaco_id
      AND r.data_reserva = NEW.data_reserva
      AND r.slot_horario_id = NEW.slot_horario_id
      AND r.status = 'APROVADA'
      AND r.id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) INTO conflito_reserva;

  IF conflito_reserva THEN
    RAISE EXCEPTION 'Conflito detectado: Este espaço já está reservado por outra pessoa nesta data.';
  END IF;

  RETURN NEW;
END;
$$;


