--
-- TOC entry 397 (class 1259 OID 97200)
-- Name: vw_choques_horarios_base; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_choques_horarios_base AS
 WITH descansos_encontrados AS (
         SELECT a1.id AS id_aula_dia_1,
            a2.id AS id_aula_dia_2
           FROM (((public.aulas a1
             JOIN public.slots_horarios s1 ON ((a1.slot_horario_id = s1.id)))
             JOIN public.aulas a2 ON (((a1.versao_id = a2.versao_id) AND (a1.professor_id = a2.professor_id) AND (a1.id <> a2.id))))
             JOIN public.slots_horarios s2 ON ((a2.slot_horario_id = s2.id)))
          WHERE ((a1.professor_id IS NOT NULL) AND (
                CASE lower((a2.dia_semana)::text)
                    WHEN 'segunda'::text THEN 1
                    WHEN 'segunda-feira'::text THEN 1
                    WHEN 'terça'::text THEN 2
                    WHEN 'terça-feira'::text THEN 2
                    WHEN 'terca'::text THEN 2
                    WHEN 'terca-feira'::text THEN 2
                    WHEN 'quarta'::text THEN 3
                    WHEN 'quarta-feira'::text THEN 3
                    WHEN 'quinta'::text THEN 4
                    WHEN 'quinta-feira'::text THEN 4
                    WHEN 'sexta'::text THEN 5
                    WHEN 'sexta-feira'::text THEN 5
                    WHEN 'sábado'::text THEN 6
                    WHEN 'sabado'::text THEN 6
                    WHEN 'domingo'::text THEN 7
                    ELSE 0
                END = ((
                CASE lower((a1.dia_semana)::text)
                    WHEN 'segunda'::text THEN 1
                    WHEN 'segunda-feira'::text THEN 1
                    WHEN 'terça'::text THEN 2
                    WHEN 'terça-feira'::text THEN 2
                    WHEN 'terca'::text THEN 2
                    WHEN 'terca-feira'::text THEN 2
                    WHEN 'quarta'::text THEN 3
                    WHEN 'quarta-feira'::text THEN 3
                    WHEN 'quinta'::text THEN 4
                    WHEN 'quinta-feira'::text THEN 4
                    WHEN 'sexta'::text THEN 5
                    WHEN 'sexta-feira'::text THEN 5
                    WHEN 'sábado'::text THEN 6
                    WHEN 'sabado'::text THEN 6
                    WHEN 'domingo'::text THEN 7
                    ELSE 0
                END % 7) + 1)) AND ((((s2.hora_inicio)::interval + '24:00:00'::interval) - (s1.hora_fim)::interval) < '10:00:00'::interval))
        ), turnos_por_dia AS (
         SELECT a.professor_id,
            a.dia_semana,
            a.versao_id
           FROM (public.aulas a
             JOIN public.slots_horarios s ON ((a.slot_horario_id = s.id)))
          WHERE (a.professor_id IS NOT NULL)
          GROUP BY a.professor_id, a.dia_semana, a.versao_id
         HAVING (count(DISTINCT s.turno) >= 3)
        ), aulas_geminadas AS (
         SELECT aulas.versao_id,
            aulas.turma_id,
            aulas.disciplina_id,
            aulas.dia_semana
           FROM public.aulas
          WHERE ((aulas.turma_id IS NOT NULL) AND (aulas.disciplina_id IS NOT NULL))
          GROUP BY aulas.versao_id, aulas.turma_id, aulas.disciplina_id, aulas.dia_semana
         HAVING (count(aulas.id) > 2)
        ), carga_horaria_validacao AS (
         SELECT a.versao_id,
            a.turma_id,
            a.disciplina_id,
            d.carga_horaria_semanal,
            count(a.id) AS total_lancado
           FROM (public.aulas a
             JOIN public.disciplinas d ON ((a.disciplina_id = d.id)))
          WHERE ((a.turma_id IS NOT NULL) AND (a.disciplina_id IS NOT NULL))
          GROUP BY a.versao_id, a.turma_id, a.disciplina_id, d.carga_horaria_semanal
        )
 SELECT a1.id AS id_aula_foco,
    a2.id AS id_aula_conflito,
    'CHOQUE_TURMA'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a1
     JOIN public.aulas a2 ON (((a1.versao_id = a2.versao_id) AND (lower((a1.dia_semana)::text) = lower((a2.dia_semana)::text)) AND (a1.slot_horario_id = a2.slot_horario_id) AND (a1.turma_id = a2.turma_id) AND (a1.id <> a2.id))))
UNION ALL
 SELECT a1.id AS id_aula_foco,
    a2.id AS id_aula_conflito,
    'CHOQUE_ESPACO'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a1
     JOIN public.aulas a2 ON (((a1.versao_id = a2.versao_id) AND (lower((a1.dia_semana)::text) = lower((a2.dia_semana)::text)) AND (a1.slot_horario_id = a2.slot_horario_id) AND (a1.espaco_id = a2.espaco_id) AND (a1.id <> a2.id))))
  WHERE (a1.espaco_id IS NOT NULL)
UNION ALL
 SELECT a1.id AS id_aula_foco,
    a2.id AS id_aula_conflito,
    'CHOQUE_DOCENTE'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a1
     JOIN public.aulas a2 ON (((a1.versao_id = a2.versao_id) AND (lower((a1.dia_semana)::text) = lower((a2.dia_semana)::text)) AND (a1.slot_horario_id = a2.slot_horario_id) AND (a1.professor_id = a2.professor_id) AND (a1.id <> a2.id))))
  WHERE (a1.professor_id IS NOT NULL)
UNION ALL
 SELECT descansos_encontrados.id_aula_dia_1 AS id_aula_foco,
    descansos_encontrados.id_aula_dia_2 AS id_aula_conflito,
    'DESCANSO_DOCENTE'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM descansos_encontrados
UNION ALL
 SELECT descansos_encontrados.id_aula_dia_2 AS id_aula_foco,
    descansos_encontrados.id_aula_dia_1 AS id_aula_conflito,
    'DESCANSO_DOCENTE'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM descansos_encontrados
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'LIMITE_TURNOS'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a
     JOIN turnos_por_dia t ON (((a.professor_id = t.professor_id) AND (lower((a.dia_semana)::text) = lower((t.dia_semana)::text)) AND (a.versao_id = t.versao_id))))
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'INDISPONIBILIDADE'::text AS tipo_choque,
    i.motivo AS mensagem_customizada
   FROM (public.aulas a
     JOIN public.professores_indisponibilidades i ON (((a.professor_id = i.professor_id) AND (lower((a.dia_semana)::text) = lower((i.dia_semana)::text)) AND (a.slot_horario_id = i.slot_horario_id))))
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'DIA_PLANEJAMENTO'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a
     JOIN public.professores p ON ((a.professor_id = p.id)))
  WHERE ((p.dia_planejamento IS NOT NULL) AND (lower((a.dia_semana)::text) ~~ (('%'::text || lower(p.dia_planejamento)) || '%'::text)))
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'AULAS_GEMINADAS'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (public.aulas a
     JOIN aulas_geminadas g ON (((a.versao_id = g.versao_id) AND (a.turma_id = g.turma_id) AND (a.disciplina_id = g.disciplina_id) AND (lower((a.dia_semana)::text) = lower((g.dia_semana)::text)))))
UNION ALL
 SELECT a1.id AS id_aula_foco,
    a2.id AS id_aula_conflito,
    'FIM_DE_SEMANA'::text AS tipo_choque,
    NULL::text AS mensagem_customizada
   FROM (((public.aulas a1
     JOIN public.slots_horarios s1 ON ((a1.slot_horario_id = s1.id)))
     JOIN public.aulas a2 ON (((a1.professor_id = a2.professor_id) AND (a1.versao_id = a2.versao_id) AND (a1.id <> a2.id))))
     JOIN public.slots_horarios s2 ON ((a2.slot_horario_id = s2.id)))
  WHERE ((a1.professor_id IS NOT NULL) AND (lower((a1.dia_semana)::text) ~~ '%sexta%'::text) AND (lower((s1.turno)::text) = 'noite'::text) AND (lower((a2.dia_semana)::text) ~~ '%segunda%'::text) AND ((lower((s2.turno)::text) ~~ '%manhã%'::text) OR (lower((s2.turno)::text) ~~ '%manha%'::text)))
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'CARGA_INCOMPLETA'::text AS tipo_choque,
    'Faltam aulas para completar a carga horária semanal.'::text AS mensagem_customizada
   FROM (public.aulas a
     JOIN carga_horaria_validacao v ON (((a.versao_id = v.versao_id) AND (a.turma_id = v.turma_id) AND (a.disciplina_id = v.disciplina_id))))
  WHERE (v.total_lancado < v.carga_horaria_semanal)
UNION ALL
 SELECT a.id AS id_aula_foco,
    NULL::uuid AS id_aula_conflito,
    'EXCESSO_CARGA'::text AS tipo_choque,
    'A carga horária semanal desta disciplina foi excedida.'::text AS mensagem_customizada
   FROM (public.aulas a
     JOIN carga_horaria_validacao v ON (((a.versao_id = v.versao_id) AND (a.turma_id = v.turma_id) AND (a.disciplina_id = v.disciplina_id))))
  WHERE (v.total_lancado > v.carga_horaria_semanal);


ALTER VIEW public.vw_choques_horarios_base OWNER TO postgres;

--
-- TOC entry 398 (class 1259 OID 97205)
-- Name: vw_choques_horarios; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_choques_horarios AS
 SELECT v.id_aula_foco,
    v.id_aula_conflito,
    v.tipo_choque,
    v.mensagem_customizada,
    a.versao_id
   FROM (public.vw_choques_horarios_base v
     JOIN public.aulas a ON ((a.id = v.id_aula_foco)));


ALTER VIEW public.vw_choques_horarios OWNER TO postgres;

--
-- TOC entry 399 (class 1259 OID 97209)
-- Name: vw_validacoes_reservas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_validacoes_reservas AS
 SELECT 'AULA_FIXA'::text AS tipo_ocupacao,
    aulas.id AS origem_id,
    aulas.espaco_id,
    aulas.dia_semana,
    aulas.slot_horario_id,
    NULL::date AS data_especifica,
    turmas.codigo AS info_solicitante_turma,
    disciplinas.nome AS info_evento_disciplina
   FROM ((public.aulas
     JOIN public.turmas ON ((aulas.turma_id = turmas.id)))
     JOIN public.disciplinas ON ((aulas.disciplina_id = disciplinas.id)))
  WHERE ((aulas.status)::text = 'ATIVO'::text)
UNION ALL
 SELECT 'RESERVA_PONTUAL'::text AS tipo_ocupacao,
    reservas_espacos.id AS origem_id,
    reservas_espacos.espaco_id,
    reservas_espacos.dia_semana,
    reservas_espacos.slot_horario_id,
    reservas_espacos.data_reserva AS data_especifica,
    reservas_espacos.nome_solicitante AS info_solicitante_turma,
    reservas_espacos.disciplina_evento AS info_evento_disciplina
   FROM public.reservas_espacos
  WHERE ((reservas_espacos.status)::text = 'APROVADA'::text);


ALTER VIEW public.vw_validacoes_reservas OWNER TO postgres;

